
import type { DeliveryProfileConfiguration } from './DeliveryProfileConfiguration.js';
import type { DeliveryProfileDiagnostics } from './DeliveryProfileDiagnostics.js';

export type DeliveryProfile = { /** Current delivery requirement and grouping policy. */ "configuration": DeliveryProfileConfiguration; /** Time the profile was created. Format: date-time. */ "created_at": string; /** Immutable revision used for new line-item snapshots. */ "current_delivery_profile_revision_id": string; /** Stable delivery profile ID. */ "delivery_profile_id": string; /** Read-only catalog and delivery-method compatibility diagnostics. */ "diagnostics"?: DeliveryProfileDiagnostics; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Caller-owned metadata. */ "metadata"?: Record<string, string>; /** Merchant-facing profile name. */ "name": string; /** Current profile lifecycle status. */ "status": "inactive" | "active" | "archived" | "revoked" | (string & {}); /** Time the profile last changed. Format: date-time. */ "updated_at": string; /** Optimistic-concurrency version for profile writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; };
